import csv

# Check RFC 4180 compliance: ensure every row has the same number of fields as the header
with open('outputs/t02_eurostat_raw.csv', 'r', newline='', encoding='utf-8') as f:
    reader = csv.reader(f)
    header = next(reader)
    print(f'Header ({len(header)} fields): {header}')

    bad_rows = []
    for i, row in enumerate(reader, start=2):
        if len(row) != len(header):
            bad_rows.append((i, len(row), row))

    if bad_rows:
        print(f'Bad rows: {len(bad_rows)}')
        for i, n, r in bad_rows[:5]:
            print(f'  Row {i}: {n} fields: {r}')
    else:
        print('All rows have correct number of fields - RFC 4180 compliant')

# Also check that fields with commas/quotes are properly quoted
with open('outputs/t02_eurostat_raw.csv', 'r', newline='', encoding='utf-8') as f:
    reader = csv.DictReader(f)
    comma_fields = 0
    for row in reader:
        for val in row.values():
            if ',' in val or '\"' in val or '\n' in val:
                comma_fields += 1
    print(f'Fields containing commas/quotes/newlines: {comma_fields}')
"
